#[path="../root-action/prepare.rs"]mod prepare;
#[path="../normalized/source.rs"]mod source;
#[path="../multi/algebra.rs"]mod algebra;
use hec_native_ic::{counted,fp::Fp,jac::Curve,poly::Poly,rng::Rng};
use std::{collections::BTreeMap,fs,io::Write};
struct Fallible{f:Fp,n:usize,rows:Vec<Option<BTreeMap<usize,u64>>>,dead:bool,rank:usize}
impl Fallible{fn new(n:usize,ell:u64)->Self{Self{f:Fp::new(ell),n,rows:vec![None;n],dead:false,rank:0}}fn k(&self)->Option<u64>{if self.dead{None}else{self.rows[self.n-1].as_ref().map(|r|*r.get(&self.n).unwrap_or(&0))}}fn insert(&mut self,v:&[u64],rhs:u64){if self.dead{return}let mut r:BTreeMap<_,_>=v.iter().copied().chain([rhs]).enumerate().filter(|x|x.1!=0).collect();while let Some((&j,&a))=r.first_key_value(){if j==self.n{self.dead=true;return}if let Some(p)=&self.rows[j]{for(&k,&b)in p{let x=self.f.sub(*r.get(&k).unwrap_or(&0),self.f.mul(a,b));if x==0{r.remove(&k);}else{r.insert(k,x);}}}else{let inv=self.f.inv(a);for x in r.values_mut(){*x=self.f.mul(*x,inv)}self.rows[j]=Some(r);self.rank+=1;return}}}}
struct Dense{f:Fp,n:usize,rows:Vec<Option<Vec<u64>>>,dead:bool,rank:usize}
impl Dense{fn new(n:usize,ell:u64)->Self{Self{f:Fp::new(ell),n,rows:vec![None;n],dead:false,rank:0}}fn k(&self)->Option<u64>{if self.dead{None}else{self.rows[self.n-1].as_ref().map(|r|r[self.n])}}fn insert(&mut self,v:&[u64],rhs:u64){if self.dead{return}let mut r=v.to_vec();r.push(rhs);for j in (0..self.n-1).rev().chain([self.n-1]){let a=r[j];if a==0{continue}if let Some(p)=&self.rows[j]{for k in 0..=self.n{r[k]=self.f.sub(r[k],self.f.mul(a,p[k]));}}else{let inv=self.f.inv(a);for x in &mut r{*x=self.f.mul(*x,inv)}self.rows[j]=Some(r);self.rank+=1;return}}if r[self.n]!=0{self.dead=true}}}
struct Hypothesis{lambda:u64,map:Vec<(usize,u64)>,s:Fallible,d:Dense,rejected_at:Option<usize>}
impl Hypothesis{fn insert(&mut self,v:&[u64],rhs:u64,index:usize){self.s.insert(v,rhs);self.d.insert(v,rhs);assert_eq!(self.s.dead,self.d.dead);if self.s.dead{if self.rejected_at.is_none(){self.rejected_at=Some(index)}}else{assert_eq!(self.s.rank,self.d.rank);assert_eq!(self.s.k(),self.d.k())}}}
fn main(){counted::disable();let root="research/hec_residual_span_20261116";let raw=fs::read_to_string(format!("{root}/incidence-oracle/ROOTS.tsv")).unwrap();let mut prefix=fs::File::create_new(format!("{root}/learn-eigenvalue/PREFIX.tsv")).unwrap();writeln!(prefix,"p\tsm\tmode\trow\tsurvivors\tunique_lambda\tk").unwrap();println!("p\tsm\tmode\trows\tsurvivors\tfirst_unique_row\tfirst_unique_k_row\tqualified_true_survivors\tfinal_lambda\tk\trejections");let mut checked=0;
for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,z)=prepare::prepare(&c);let f=Fp::new(ell);assert_eq!((ell-1)%5,0);let w=(2..ell).map(|a|f.pow(a,(ell-1)/5)).find(|&x|x!=1).unwrap();let mut candidates=vec![];let mut l=1;for _ in 1..5{l=f.mul(l,w);candidates.push(l);}candidates.sort_unstable();candidates.dedup();assert_eq!(candidates.len(),4);let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026112500^p);
for sm in [1,17]{let d=c.mul(&base,sm);let qualification=1+rng.below(ell-1);let target=c.mul(&d,qualification);
for mode in [0,1]{let mut arms=vec![];let mut cols=0;for &lambda in &candidates{let mut map=vec![(usize::MAX,0);fb.len()];let mut r=0;for j in 0..fb.len(){if map[j].0!=usize::MAX{continue}let(mut x,y,mut wt)=(fb[j].0,fb[j].1,1);for _ in 0..5{let q=fb.binary_search_by_key(&x,|p|p.0).unwrap();assert_eq!(map[q].0,usize::MAX);map[q]=(r,if fb[q].1==y{wt}else{assert_eq!(fb[q].1,c.fp.neg(y));f.neg(wt)});x=c.fp.mul(x,z);wt=f.mul(wt,lambda);}r+=1;}cols=r;let mut arm=Hypothesis{lambda,map,s:Fallible::new(cols+1,ell),d:Dense::new(cols+1,ell),rejected_at:None};if let Some((_,v))=source::equation(&c,&d,&fb,&arm.map,cols,ell){let mut v=v;v.push(0);arm.insert(&v,1,0);}arms.push(arm);}
let(mut index,mut first_eigen,mut first_k)=(0,None,None);for line in raw.lines().skip(1){let v:Vec<_>=line.split('\t').collect();if v[0].parse::<u64>().unwrap()!=p||v[1].parse::<u64>().unwrap()!=sm{continue}let support:Vec<Vec<u64>>=v[5].split(',').map(|x|x.split(':').map(|v|v.parse().unwrap()).collect()).collect();if mode==1&&!support.iter().any(|x|x[0]==0){continue}index+=1;let a=v[3].parse::<u64>().unwrap();for arm in &mut arms{if arm.s.dead{continue}let mut coeff=vec![0;cols+1];for x in &support{let j=fb.binary_search_by_key(&x[1],|p|p.0).unwrap();assert_eq!(arm.map[j].0,x[0]as usize);let wt=if x[2]==fb[j].1{arm.map[j].1}else{assert_eq!(x[2],c.fp.neg(fb[j].1));f.neg(arm.map[j].1)};coeff[x[0]as usize]=f.add(coeff[x[0]as usize],wt);}coeff[cols]=1;arm.insert(&coeff,f.neg(a),index);checked+=1;}let live:Vec<_>=arms.iter().filter(|a|!a.s.dead).collect();assert!(!live.is_empty());let unique=if live.len()==1{Some(live[0].lambda)}else{None};let k=if live.len()==1{live[0].s.k()}else{None};if unique.is_some()&&first_eigen.is_none(){first_eigen=Some(index)}if k.is_some()&&first_k.is_none(){first_k=Some(index)}writeln!(prefix,"{p}\t{sm}\t{mode}\t{index}\t{}\t{}\t{}",live.len(),unique.map_or("none".into(),|v|v.to_string()),k.map_or("none".into(),|v|v.to_string())).unwrap();}
let live:Vec<_>=arms.iter().filter(|a|!a.s.dead).collect();let image=algebra::action(&c,&d,z);let true_survivors=live.iter().filter(|a|c.mul(&d,a.lambda)==image).count();assert_eq!(true_survivors,1);let lambda=if live.len()==1{Some(live[0].lambda)}else{None};let k=if live.len()==1{live[0].s.k()}else{None};if let Some(k)=k{assert_eq!(c.mul(&d,k),target)}let rejected=arms.iter().map(|a|format!("{}:{}",a.lambda,a.rejected_at.map_or("live".into(),|x|x.to_string()))).collect::<Vec<_>>().join(",");println!("{p}\t{sm}\t{mode}\t{index}\t{}\t{}\t{}\t{true_survivors}\t{}\t{}\t{rejected}",live.len(),first_eigen.map_or("none".into(),|x|x.to_string()),first_k.map_or("none".into(),|x|x.to_string()),lambda.map_or("none".into(),|x|x.to_string()),k.map_or("none".into(),|x|x.to_string()));}}}
eprintln!("streams=12 checked_hypothesis_prefixes={checked} opposite_pivot_orders_agree=true true_geometric_eigenvalue_survives=true no_character_input_to_inference=true no_complete_cost_claim=true");}
